// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount, address player) internal {
        vm.assume(amount > 0 && amount != 1);
        vm.assume(player != address(0));
        try c.AdjustBetAmounts(amount) {} catch { return; }
        assertTrue(c.currentBetLimit() == amount);
    }

    function testFuzz_run(uint256 amount, address player) public {
        _run(amount, player);
    }

    receive() external payable {}
}
